if ~strcmp(DisPlayLKDoG,"Select")
    FrameNumLKDoG = 2; %[control:spinner:8cdf]{"position":[21,22]}
      %[control:button:8193]{"position":[5,6]}
    opticflowLKDoG = opticalFlowLKDoG;
    [~,numFrames]= OptFlow(LKDoGVid,opticflowLKDoG,FrameNumLKDoG,DisPlayLKDoG);
else
    warning("Select a valid option.")
end
%%
%[text] ### Horn-Schunck Method Applied
%[text] ![](text:image:7f4e) **Try.** Use the Horn-Schunck method to track the motion of a toy car.
%[text] 1. *Select a display mode.*
%[text] 2. *Select a starting point frame number.*
%[text] 3. *Press 'View Results of the Horn-Schunck Method' to see the outcome.*  \
